---@class QTEShared
---@field GetInstance fun(self:QTEShared):QTEShared
local QTEShared = Class('QTEShared', Singleton)

---@type QTEConstants
local QTEConstants = import("Game.QTE.QTEConstants")

function QTEShared:__init()
    --
    self.curStep = nil
end

function QTEShared:__delete()
    --
    self.curStep = nil
end

function QTEShared:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

function QTEShared:GetCurrentStep()
    
    --return QTEConstants.QTESavePoint.NotStart
    
    if QTEReview then
        return QTEConstants.QTESavePoint.NotStart
    end

    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if isNull(playerComponent) then
        return QTEConstants.QTESavePoint.NotStart
    end

    if self.curStep == nil then
        self.curStep = checkNumber(playerComponent.playerDojo.opStepId)
    end

    return self.curStep
end

function QTEShared:IncreaseStep()

    if QTEReview then
        return
    end
    
    self.curStep = checkNumber(self.curStep)
    
    self.curStep = self.curStep + 1
    
    GameUtils.Request(Interfaces.PlayerSetOpStep, {stepId = self.curStep})
    
end

function QTEShared:SetStep(step)

    if QTEReview then
        return
    end
    
    if self.curStep == step then
        return
    end

    self.curStep = step

    GameUtils.Request(Interfaces.PlayerSetOpStep, {stepId = self.curStep})
    
end

return QTEShared